// ❌ OLD: Indexing raw arguments directly assumes the app is running on Express HTTP.
// If this guard is applied to a WebSocket gateway or Microservice controller, it crashes!
import { CanActivate, ExecutionContext, Injectable } from '@nestjs/common';

@Injectable()
export class BrittleAuthGuard implements CanActivate {
  canActivate(context: ExecutionContext): boolean {
    const req = context.getArgs()[0]; // ❌ Hardcoded index assumption
    const token = req.headers['authorization'];
    return !!token;
  }
}

import { CanActivate, ExecutionContext, Injectable } from '@nestjs/common';
import { Reflector } from '@nestjs/core';

@Injectable()
export class UniversalAuthGuard implements CanActivate {
  constructor(private reflector: Reflector) {}

  canActivate(context: ExecutionContext): boolean {
    // ✅ Read metadata from controller handler or class:
    const isPublic = this.reflector.getAllAndOverride<boolean>('isPublic', [
      context.getHandler(),
      context.getClass()
    ]);
    if (isPublic) return true;

    // ✅ Safely extract request based on protocol type:
    if (context.getType() === 'http') {
      const req = context.switchToHttp().getRequest();
      return !!req.headers['authorization'];
    }
    if (context.getType() === 'ws') {
      const client = context.switchToWs().getClient();
      return !!client.handshake?.headers?.authorization;
    }
    return true;
  }
}
